import{_ as o,o as a,c as d,ag as s}from"./chunks/framework.B5ULsuav.js";const g=JSON.parse('{"title":"认知路径","description":"","frontmatter":{},"headers":[],"relativePath":"30-学习路径/path-认知路径.md","filePath":"30-学习路径/path-认知路径.md","lastUpdated":1778155802000}'),i={name:"30-学习路径/path-认知路径.md"};function r(n,t,u,h,l,e){return a(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="认知路径" tabindex="-1">认知路径 <a class="header-anchor" href="#认知路径" aria-label="Permalink to &quot;认知路径&quot;">​</a></h1><blockquote><p>系统学习路径：按次第建立对七大核心心智模型的完整理解。 适合希望系统建立智慧体系的学习者。</p></blockquote><hr><h2 id="路径总览" tabindex="-1">路径总览 <a class="header-anchor" href="#路径总览" aria-label="Permalink to &quot;路径总览&quot;">​</a></h2><p><strong>先明理，再修心，后行事。</strong> 天人合一是世界观基础——先知道&quot;为什么&quot;，再练&quot;怎么做&quot;。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天人合一（世界观 ── 先明理）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>对境不住（心法：对外不动心）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>对法不执（心法：对内不执方法）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>自然务实（方法论：抓核心做实事）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>圆融中和（处世智慧：不走极端）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>历境炼心（实践：在事上磨）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>性命双修（圆满：身心一体）</span></span></code></pre></div><blockquote><p><strong>整体观贯穿全程</strong>：每一个阶段都要用整体观的三个维度（跨时间/跨立场/跨层次）来检验——不是学完一个丢一个，是层层叠加、越用越深。详见 <a href="/liaokongjushi-wisdom/meta-整体观">整体观元方法</a>。</p></blockquote><hr><h2 id="第一阶段-天人合一-先建立世界观" tabindex="-1">第一阶段：天人合一 | 先建立世界观 <a class="header-anchor" href="#第一阶段-天人合一-先建立世界观" aria-label="Permalink to &quot;第一阶段：天人合一 | 先建立世界观&quot;">​</a></h2><p><strong>核心问题</strong>：为什么要这样修行？终极坐标系是什么？</p><p><strong>目标</strong>：理解&quot;万物一体、因果不空&quot;——这是所有心法和实践的根基。</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>参考资料</th><th>原文出处</th></tr></thead><tbody><tr><td>1.1</td><td>理解&quot;缘起性空&quot;——一切不永恒，所以可改变、不必执</td><td><a href="/liaokongjushi-wisdom/10-核心模型/model-天人合一">model-天人合一</a></td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经10分-缘起性空">金刚经10分-缘起性空</a></td></tr><tr><td>1.2</td><td>理解&quot;因果不空&quot;——因果分条算，过去的因+现在的缘=未来的果</td><td>模型原子：因果不空</td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经10分-万法皆空因果不空">金刚经10分-万法皆空因果不空</a>、<a href="/liaokongjushi-wisdom/60-原文段落/答疑2014-因果分条算">答疑2014-因果分条算</a></td></tr><tr><td>1.3</td><td>感受&quot;箩筐与大海&quot;——你不是要&quot;变成&quot;大海，你本来就是</td><td>模型原子：箩筐与大海</td><td><a href="/liaokongjushi-wisdom/60-原文段落/答疑2014-箩筐与大海">答疑2014-箩筐与大海</a></td></tr><tr><td>1.4</td><td>建立&quot;一体同观&quot;——利人即利己，这是所有善行的终极理由</td><td>模型原子：一体同观</td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经18分-一体同观">金刚经18分-一体同观</a></td></tr></tbody></table><p><strong>实战应用</strong>：</p><ul><li>遇到&quot;为什么又是我&quot;的委屈时，用因果分条算——过去的因是什么？现在的缘我能做什么？</li><li><a href="/liaokongjushi-wisdom/20-专题研究/topic-生死观">如何面对生死</a> — 天人合一的终极应用</li></ul><p><strong>检验标准</strong>：遇到不顺时，第一反应从&quot;为什么是我&quot;变成&quot;因缘是什么&quot;。</p><p><strong>&gt; 常见卡点</strong>：觉得天人合一是&quot;玄学&quot;、和日常生活没关系。突破——从&quot;因果分条算&quot;开始，这是最接地气的入口。不需要先相信&quot;万物一体&quot;，先试试&quot;因果分条算&quot;看能不能帮你看清问题。</p><blockquote><p><strong>关键金句</strong>：&quot;万法皆空，因果不空。&quot; 原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经10分-万法皆空因果不空">金刚经10分-万法皆空因果不空</a></p></blockquote><hr><h2 id="第二阶段-对境不住-不被现象迷惑" tabindex="-1">第二阶段：对境不住 | 不被现象迷惑 <a class="header-anchor" href="#第二阶段-对境不住-不被现象迷惑" aria-label="Permalink to &quot;第二阶段：对境不住 | 不被现象迷惑&quot;">​</a></h2><p><strong>核心问题</strong>：为什么我总是被外界带着跑？</p><p><strong>目标</strong>：学会觉察——知道自己在做什么、想什么，不被现象牵着走。</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>参考资料</th><th>原文出处</th></tr></thead><tbody><tr><td>2.1</td><td>理解&quot;应无所住而生其心&quot;——不执着不等于不知道</td><td><a href="/liaokongjushi-wisdom/10-核心模型/model-对境不住">model-对境不住</a></td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经10分-应无所住生心">金刚经10分-应无所住生心</a></td></tr><tr><td>2.2</td><td>学会&quot;离相&quot;——不是逃避现象，是客观地看待现象</td><td>模型原子：离相</td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-离相">金刚经5分-离相</a></td></tr><tr><td>2.3</td><td>掌握&quot;理智&quot;操作手柄——情绪上来时启动理智，问&quot;我为什么不平静？&quot;</td><td>模型原子：理智</td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a></td></tr><tr><td>2.4</td><td>理解&quot;三心不可得&quot;——过去已去，未来未至，现在无住</td><td>模型原子：三心不可得</td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经18分-三心不可得">金刚经18分-三心不可得</a></td></tr></tbody></table><p><strong>实战应用</strong>：</p><ul><li><a href="/liaokongjushi-wisdom/20-专题研究/topic-情绪">如何处理情绪</a> — 对境不住操作法（觉察→暂停→观照→放下）</li><li><a href="/liaokongjushi-wisdom/20-专题研究/topic-焦虑">如何面对焦虑</a> — 焦虑是对未来&quot;相&quot;的执着</li></ul><p><strong>检验标准</strong>：被人批评时，第一反应不是反驳，而是先听完。</p><p><strong>&gt; 常见卡点</strong>：把&quot;不动心&quot;理解成&quot;压抑情绪&quot;——嘴上说没事，心里咬牙切齿。突破——不是压着，是看着。像看河水流淌，看着情绪但不跳进去。参考四步操作法（觉察→暂停→观照→放下）。</p><blockquote><p><strong>关键金句</strong>：&quot;不平静时问自己：&#39;我为什么要不平静？这样正确吗？&#39;&quot; 原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a></p></blockquote><hr><h2 id="第三阶段-对法不执-连方法也放下" tabindex="-1">第三阶段：对法不执 | 连方法也放下 <a class="header-anchor" href="#第三阶段-对法不执-连方法也放下" aria-label="Permalink to &quot;第三阶段：对法不执 | 连方法也放下&quot;">​</a></h2><p><strong>核心问题</strong>：我知道不该被现象带跑，但为什么还是放不下&quot;我在修行&quot;？</p><p><strong>目标</strong>：从&quot;不被外部带跑&quot;深化到&quot;不执着于任何东西，包括方法、功德、境界&quot;。</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>参考资料</th><th>原文出处</th></tr></thead><tbody><tr><td>3.1</td><td>理解&quot;法无定法&quot;——没有一个固定方法叫&quot;开悟&quot;，因病与药</td><td><a href="/liaokongjushi-wisdom/10-核心模型/model-对法不执">model-对法不执</a></td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经7分-无有定法">金刚经7分-无有定法</a></td></tr><tr><td>3.2</td><td>理解&quot;法尚应舍&quot;——过了河要放下船，但病没好不能不吃药</td><td>模型原子：法尚应舍</td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经6分-法尚应舍">金刚经6分-法尚应舍</a></td></tr><tr><td>3.3</td><td>学习不执功德相——做了但不觉得&quot;我在做&quot;，帮了就放下</td><td>模型原子：不执功德相</td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经10分-应无所住生心">金刚经10分-应无所住生心</a></td></tr><tr><td>3.4</td><td>理解&quot;信心不逆&quot;——真信不是嘴上说，是行为上自然流露</td><td>模型原子：信心不逆</td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经15分-信心不逆">金刚经15分-信心不逆</a></td></tr></tbody></table><p><strong>实战应用</strong>：</p><ul><li><a href="/liaokongjushi-wisdom/20-专题研究/topic-财富与布施">如何看待财富与布施</a> — 布施后不求功德</li><li><a href="/liaokongjushi-wisdom/20-专题研究/topic-忍辱与原谅">如何面对忍辱与原谅</a> — 放下&quot;被侮辱&quot;的标签</li></ul><p><strong>检验标准</strong>：你做了一件好事之后，心里有没有&quot;我做了好事&quot;的感觉？有也没关系——觉察到就是进步。</p><p><strong>&gt; 常见卡点</strong>：把&quot;不执&quot;当成&quot;不修&quot;——&quot;反正法无定法，怎么都行&quot;。突破——对法不执 ≠ 不修行。病没好药不能停，放下的是对药的执着，不是药本身。</p><blockquote><p><strong>关键金句</strong>：&quot;法尚应舍，何况非法。&quot; 原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经6分-法尚应舍">金刚经6分-法尚应舍</a></p></blockquote><hr><h2 id="第四阶段-自然务实-抓核心-做实事" tabindex="-1">第四阶段：自然务实 | 抓核心，做实事 <a class="header-anchor" href="#第四阶段-自然务实-抓核心-做实事" aria-label="Permalink to &quot;第四阶段：自然务实 | 抓核心，做实事&quot;">​</a></h2><p><strong>核心问题</strong>：道理懂了，怎么落实到行动上？</p><p><strong>目标</strong>：把道理变成行动——不绕弯子，抓核心，做该做的事。</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>参考资料</th><th>原文出处</th></tr></thead><tbody><tr><td>4.1</td><td>理解&quot;直指人心、抓住核心&quot;——学任何东西先抓最核心的一点</td><td><a href="/liaokongjushi-wisdom/10-核心模型/model-自然务实">model-自然务实</a></td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经1分-抓住核心">金刚经1分-抓住核心</a>、<a href="/liaokongjushi-wisdom/60-原文段落/金刚经1分-直指人心">金刚经1分-直指人心</a></td></tr><tr><td>4.2</td><td>理解&quot;无为即无妄为&quot;——不是不做，是按客观实际情况去做</td><td>模型原子：无为即无妄为</td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经11分-无为即无妄为">金刚经11分-无为即无妄为</a></td></tr><tr><td>4.3</td><td>学会&quot;攀缘vs随缘&quot;——随缘是根据客观条件做最合理方案，不是随便</td><td>模型原子：攀缘vs随缘</td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经3分-攀缘与随缘">金刚经3分-攀缘与随缘</a></td></tr><tr><td>4.4</td><td>实践&quot;信解行证&quot;四步法——先相信→理解→行动→亲身体证</td><td>模型原子：信解行证</td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经7分-信解行证">金刚经7分-信解行证</a></td></tr></tbody></table><p><strong>实战应用</strong>：</p><ul><li><a href="/liaokongjushi-wisdom/20-专题研究/topic-选择">如何做出选择</a> — 用&quot;抓核心&quot;做决策</li><li><a href="/liaokongjushi-wisdom/20-专题研究/topic-工作修行">在工作中修行</a> — 工作即道场</li></ul><p><strong>检验标准</strong>：遇到问题，你更多在想&quot;怎么办&quot;还是在想&quot;为什么又是我&quot;？</p><p><strong>&gt; 常见卡点</strong>：&quot;抓核心&quot;变成不学习的借口——&quot;抓核心嘛，其他的不用学了&quot;。突破——抓核心的前提是你已经了解了全貌。先学全，再提炼。</p><blockquote><p><strong>关键金句</strong>：&quot;做就是了。行动胜过千言万语。&quot; 原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经11分-无为即无妄为">金刚经11分-无为即无妄为</a></p></blockquote><hr><h2 id="第五阶段-圆融中和-不走极端" tabindex="-1">第五阶段：圆融中和 | 不走极端 <a class="header-anchor" href="#第五阶段-圆融中和-不走极端" aria-label="Permalink to &quot;第五阶段：圆融中和 | 不走极端&quot;">​</a></h2><p><strong>核心问题</strong>：我努力了，但总是走极端——要么太紧，要么太松。</p><p><strong>目标</strong>：找到中道——在每一件事情上做到恰到好处。</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>参考资料</th><th>原文出处</th></tr></thead><tbody><tr><td>5.1</td><td>理解&quot;守中&quot;——看准最佳时机，不盲动不妄动</td><td><a href="/liaokongjushi-wisdom/10-核心模型/model-圆融中和">model-圆融中和</a></td><td><a href="/liaokongjushi-wisdom/60-原文段落/道德经5章-多言数穷不如守中">道德经5章-多言数穷不如守中</a></td></tr><tr><td>5.2</td><td>学习&quot;离边见&quot;——凡夫开口闭口都是边见，跳出非此即彼</td><td>模型原子：离边见</td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经1分-离边见">金刚经1分-离边见</a></td></tr><tr><td>5.3</td><td>理解&quot;非法非非法&quot;——方法不是绝对的，也不是没用的（钥匙开锁）</td><td>模型原子：非法非非法</td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经7分-非法非非法">金刚经7分-非法非非法</a></td></tr><tr><td>5.4</td><td>以整体观定善恶——对大众整体有益就是善，不是没有标准</td><td>模型原子：整体观定善恶</td><td><a href="/liaokongjushi-wisdom/60-原文段落/论坛-整体观定善恶">论坛-整体观定善恶</a>、<a href="/liaokongjushi-wisdom/60-原文段落/金刚经7分-整体观是非对错">金刚经7分-整体观是非对错</a></td></tr></tbody></table><p><strong>实战应用</strong>：</p><ul><li><a href="/liaokongjushi-wisdom/20-专题研究/topic-人际关系">如何处理人际关系</a> — 待人处事的中道</li><li><a href="/liaokongjushi-wisdom/20-专题研究/topic-亲子教育">如何教育子女</a> — 不偏不倚的教育</li></ul><p><strong>检验标准</strong>：在争论中，你能不能同时说出对方立场中合理的那一点？</p><p><strong>&gt; 常见卡点</strong>：把中道当成&quot;和稀泥&quot;——两边各打五十大板。突破——中道不是没有立场，是跳出二元后看到的最佳方案。归宗斩蛇——该斩就斩，这是中道（整体利益）。</p><blockquote><p><strong>关键金句</strong>：&quot;守中不是停在中间不动，是不走极端。就像开车，要不断微调方向。&quot; 原文：<a href="/liaokongjushi-wisdom/60-原文段落/道德经5章-多言数穷不如守中">道德经5章-多言数穷不如守中</a></p></blockquote><hr><h2 id="第六阶段-历境炼心-在事上磨" tabindex="-1">第六阶段：历境炼心 | 在事上磨 <a class="header-anchor" href="#第六阶段-历境炼心-在事上磨" aria-label="Permalink to &quot;第六阶段：历境炼心 | 在事上磨&quot;">​</a></h2><p><strong>核心问题</strong>：我在静坐时很平静，但一遇到事情就乱。</p><p><strong>目标</strong>：在每一个生活场景中磨炼心性——顺境不飘，逆境不垮。</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>参考资料</th><th>原文出处</th></tr></thead><tbody><tr><td>6.1</td><td>理解&quot;烦恼即菩提&quot;——一切烦恼为如来种，烦恼是觉悟的材料</td><td><a href="/liaokongjushi-wisdom/10-核心模型/model-历境炼心">model-历境炼心</a></td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-烦恼即菩提">金刚经5分-烦恼即菩提</a></td></tr><tr><td>6.2</td><td>掌握&quot;不怕念起只怕觉迟&quot;——有杂念不可怕，觉察不到才可怕</td><td>模型原子：不怕念起只怕觉迟</td><td><a href="/liaokongjushi-wisdom/60-原文段落/答疑2021-不怕念起只怕觉迟">答疑2021-不怕念起只怕觉迟</a></td></tr><tr><td>6.3</td><td>学习&quot;顺逆皆修&quot;——风和日丽谁都能静心，风雨交加才是真功夫</td><td>模型原子：顺逆皆修</td><td><a href="/liaokongjushi-wisdom/60-原文段落/答疑2014-顺逆皆修与冤亲平等">答疑2014-顺逆皆修与冤亲平等</a></td></tr><tr><td>6.4</td><td>实践&quot;冤亲平等&quot;——最难修的是面对不喜欢的人还能保持平等心</td><td>模型原子：冤亲平等</td><td><a href="/liaokongjushi-wisdom/60-原文段落/答疑2014-顺逆皆修与冤亲平等">答疑2014-顺逆皆修与冤亲平等</a></td></tr></tbody></table><p><strong>实战应用</strong>：</p><ul><li><a href="/liaokongjushi-wisdom/20-专题研究/topic-工作修行">在工作中修行</a> — 工作场景中的炼心</li><li><a href="/liaokongjushi-wisdom/20-专题研究/topic-疾病与健康">如何面对疾病与健康</a> — 病中的炼心</li><li><a href="/liaokongjushi-wisdom/20-专题研究/topic-忍辱与原谅">如何面对忍辱与原谅</a> — 被伤害时的炼心</li></ul><p><strong>检验标准</strong>：遇到让你生气的事，多久能平静下来？时间在缩短就是进步。</p><p><strong>&gt; 常见卡点</strong>：修行变成&quot;表演&quot;——在同修面前很精进，回家就回到老样子。突破——细致圆满是在没人看的时候依然细致。修行是给自己修的。</p><blockquote><p><strong>关键金句</strong>：&quot;一切烦恼为如来种——烦恼是觉悟的机会，不是敌人。&quot; 原文：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-烦恼即菩提">金刚经5分-烦恼即菩提</a></p></blockquote><hr><h2 id="第七阶段-性命双修-身心圆满" tabindex="-1">第七阶段：性命双修 | 身心圆满 <a class="header-anchor" href="#第七阶段-性命双修-身心圆满" aria-label="Permalink to &quot;第七阶段：性命双修 | 身心圆满&quot;">​</a></h2><p><strong>核心问题</strong>：如何将一切理论和实践整合到生命中？</p><p><strong>目标</strong>：性命双修——既要明心，也要修身，达到形神俱妙。</p><table tabindex="0"><thead><tr><th>步骤</th><th>内容</th><th>参考资料</th><th>原文出处</th></tr></thead><tbody><tr><td>7.1</td><td>理解&quot;神守黄房&quot;——轻轻返观中丹田，这是顿法的唯一动作</td><td><a href="/liaokongjushi-wisdom/10-核心模型/model-性命双修">model-性命双修</a></td><td><a href="/liaokongjushi-wisdom/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></td></tr><tr><td>7.2</td><td>掌握&quot;似守非守&quot;——不可用心守，不可无意求</td><td>模型原子：似守非守</td><td><a href="/liaokongjushi-wisdom/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></td></tr><tr><td>7.3</td><td>体会&quot;养气忘言守&quot;——养气（命功）和降心（性功）是一件事</td><td>模型原子：养气忘言守</td><td><a href="/liaokongjushi-wisdom/60-原文段落/中论丹道-养气忘言守">中论丹道-养气忘言守</a></td></tr><tr><td>7.4</td><td>了解&quot;师力加持&quot;——顿法的关键助力，能量共振不是迷信</td><td>模型原子：师力加持</td><td><a href="/liaokongjushi-wisdom/60-原文段落/中论丹道-师力加持">中论丹道-师力加持</a></td></tr></tbody></table><p><strong>实战应用</strong>：</p><ul><li><a href="/liaokongjushi-wisdom/20-专题研究/topic-入门实修">如何开始实修</a> — 实修的起点</li><li><a href="/liaokongjushi-wisdom/20-专题研究/topic-修行进阶">修行进阶</a> — 从入门到深入</li></ul><p><strong>检验标准</strong>：日常中是否能同时感受到身体的放松和心的清净？</p><p><strong>&gt; 常见卡点</strong>：追感觉——有气感就觉得&quot;修得好&quot;，没感觉就觉得&quot;退步了&quot;。突破——&quot;但安神息，不运火而火自运&quot;，感觉来来去去，不追。出问题第一反应是松，不是调整技术。</p><blockquote><p><strong>关键金句</strong>：&quot;不可用心守，不可无意求。养气忘言守，降心为不为。&quot; 原文：<a href="/liaokongjushi-wisdom/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a>、<a href="/liaokongjushi-wisdom/60-原文段落/中论丹道-养气忘言守">中论丹道-养气忘言守</a></p></blockquote><hr><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><h3 id="速度建议" tabindex="-1">速度建议 <a class="header-anchor" href="#速度建议" aria-label="Permalink to &quot;速度建议&quot;">​</a></h3><ul><li><strong>第一阶段（天人合一）</strong>：1-2周，建立因果观和一体观——这是所有后续阶段的地基</li><li><strong>第二阶段（对境不住）</strong>：2-3周，打好觉察基础——这是最核心的心法功夫</li><li><strong>第三阶段（对法不执）</strong>：2-3周，反复体会&quot;放下&quot;——最容易误解的阶段</li><li><strong>第四阶段（自然务实）</strong>：1-2周，重点在行动——把前三个阶段落实到做事</li><li><strong>第五阶段（圆融中和）</strong>：2-3周，在生活中找&quot;度&quot;</li><li><strong>第六阶段（历境炼心）</strong>：长期，每一个烦恼都是一次考试</li><li><strong>第七阶段（性命双修）</strong>：长期，一日修行一日功</li></ul><blockquote><p>不必按部就班地&quot;学完&quot;——遇到哪些问题，就去对应的阶段找答案。七个阶段是螺旋上升的，不是一条直线走到底。</p></blockquote><h3 id="每个阶段的三步法" tabindex="-1">每个阶段的三步法 <a class="header-anchor" href="#每个阶段的三步法" aria-label="Permalink to &quot;每个阶段的三步法&quot;">​</a></h3><ol><li><strong>读原文</strong> → 先读本阶段的原文出处（上表中&quot;原文出处&quot;列）</li><li><strong>读模型</strong> → 再读对应的模型页面，看系统化的解读</li><li><strong>做检验</strong> → 用检验标准自测，达不到就继续练</li></ol><h3 id="最佳配套阅读" tabindex="-1">最佳配套阅读 <a class="header-anchor" href="#最佳配套阅读" aria-label="Permalink to &quot;最佳配套阅读&quot;">​</a></h3><ul><li><a href="/liaokongjushi-wisdom/meta-整体观">整体观元方法</a> — 贯穿全路径的操作系统，建议第一阶段就了解</li><li><a href="/liaokongjushi-wisdom/03-Output/核心摘要">核心摘要</a> — 全体系精华浓缩</li><li><a href="/liaokongjushi-wisdom/03-Output/学习指南">学习指南</a> — 按学习阶段组织的指南</li></ul><hr><blockquote><p>创建日期：2026-05-06 | 修订：2026-05-07（修正阶段顺序：天人合一移至第1阶段；每步骤新增原文段落链接；新增每阶段常见卡点+突破方法；新增整体观贯穿提示；新增三步入手法）</p></blockquote>`,88)])])}const p=o(i,[["render",r]]);export{g as __pageData,p as default};
